  color: var(--text-h);
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.cart-dropped-tag {
  font-size: 13px;
  color: var(--text);
  white-space: nowrap;
}

.cart-unit-price,
.cart-subtotal,
.cart-quantity {
  font-family: var(--mono);
  font-size: 15px;
}

.cart-subtotal {
  color: var(--text-h);
