  width: 24px;
  height: 24px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font: inherit;
  font-size: 15px;
  line-height: 1;
  color: var(--text-h);
  background: transparent;
  border: 1px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
}

.cart-step:hover:not(:disabled) {
  border-color: var(--accent-border);
  background: var(--accent-bg);
}

.cart-step:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

