  margin: 16px 0 0;
  color: var(--text);
}

.cart-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin: 16px 0 0;
  color: var(--text-h);
}

.cart-total strong {
  font-family: var(--mono);
  font-weight: 500;
}

